#!/usr/bin/env node
// Copyright (c) Meta Platforms, Inc. and affiliates.

/**
 * @file Turn an untrusted pr-visual artifact into publishable evidence.
 *
 * @input  verdict.json + before/after/diff PNGs emitted by PR-controlled CI
 * @output schema-validated, decoded/re-encoded PNGs and a report whose HTML is
 *         generated by DEFAULT-BRANCH code
 *
 * This script runs only in the trusted `workflow_run` publisher. It never
 * imports or executes a file from the artifact. A fork may choose every byte
 * in its artifact, so paths, counts, identity fields and image bytes are all
 * validated before anything is copied onto the shared GitHub Pages origin.
 */

import fs from 'node:fs';
import path from 'node:path';
import {PNG} from 'pngjs';

import {renderReport} from './lib/report.mjs';

const args = process.argv.slice(2);
const flag = name => {
  const index = args.indexOf(`--${name}`);
  return index === -1 ? null : args[index + 1];
};

const input = path.resolve(flag('input') ?? 'visual');
const output = path.resolve(flag('output') ?? 'trusted-visual');
const pr = Number(flag('pr'));
const headSha = flag('head-sha') ?? '';
const runId = flag('run-id') ?? '';
const runAttempt = flag('run-attempt') ?? '';

const KEY = /^[A-Za-z0-9._-]{1,240}$/;
const SHA = /^[0-9a-f]{40}$/;
const MAX_CHANGES = 240;
const MAX_PNG_BYTES = 12 * 1024 * 1024;
const MAX_EDGE = 5000;

function fail(message) {
  throw new Error(`visual evidence rejected: ${message}`);
}

if (!Number.isSafeInteger(pr) || pr <= 0) fail('invalid PR number');
if (!SHA.test(headSha)) fail('invalid trusted head SHA');
if (!/^\d+$/.test(runId) || !/^\d+$/.test(runAttempt)) fail('invalid run identity');

const verdictPath = path.join(input, 'verdict.json');
if (!fs.existsSync(verdictPath)) fail('verdict.json is missing');
if (fs.lstatSync(verdictPath).isSymbolicLink()) fail('verdict.json is a symlink');
const verdict = JSON.parse(fs.readFileSync(verdictPath, 'utf8'));

if (verdict.version !== 1) fail(`unsupported verdict version ${verdict.version}`);
if (!['pass', 'changed', 'failed', 'skipped'].includes(verdict.status)) {
  fail(`invalid verdict status ${verdict.status}`);
}
if (String(verdict.context?.runId ?? '') !== runId) {
  fail(`verdict run ${verdict.context?.runId ?? 'missing'} does not match ${runId}`);
}
if (verdict.context?.headSha && verdict.context.headSha !== headSha) {
  fail(`verdict head ${verdict.context.headSha} does not match trusted head ${headSha}`);
}
if (!Array.isArray(verdict.changes) || verdict.changes.length > MAX_CHANGES) {
  fail(`invalid change count ${verdict.changes?.length ?? 'missing'}`);
}

const seen = new Set();
for (const change of verdict.changes) {
  if (!KEY.test(change.key ?? '')) fail(`invalid shot key ${JSON.stringify(change.key)}`);
  if (seen.has(change.key)) fail(`duplicate shot key ${change.key}`);
  seen.add(change.key);
  if (!Number.isFinite(Number(change.diffPixels)) || Number(change.diffPixels) < 0) {
    fail(`invalid diff pixel count for ${change.key}`);
  }
}

fs.rmSync(output, {recursive: true, force: true});
for (const kind of ['before', 'after', 'diff']) {
  fs.mkdirSync(path.join(output, kind), {recursive: true});
}

/** Decode + re-encode: validates the bytes and strips ancillary metadata. */
function copyPng(kind, key) {
  const source = path.join(input, 'report', kind, `${key}.png`);
  if (!fs.existsSync(source)) fail(`${kind}/${key}.png is missing`);
  const stat = fs.lstatSync(source);
  if (!stat.isFile() || stat.isSymbolicLink()) fail(`${kind}/${key}.png is not a regular file`);
  if (stat.size <= 0 || stat.size > MAX_PNG_BYTES) fail(`${kind}/${key}.png has invalid size`);

  let image;
  try {
    image = PNG.sync.read(fs.readFileSync(source), {checkCRC: true});
  } catch (error) {
    fail(`${kind}/${key}.png is not a valid PNG: ${error.message}`);
  }
  if (
    image.width <= 0 ||
    image.height <= 0 ||
    image.width > MAX_EDGE ||
    image.height > MAX_EDGE
  ) {
    fail(`${kind}/${key}.png has invalid dimensions ${image.width}x${image.height}`);
  }
  fs.writeFileSync(path.join(output, kind, `${key}.png`), PNG.sync.write(image));
}

for (const {key} of verdict.changes) {
  for (const kind of ['before', 'after', 'diff']) copyPng(kind, key);
}

const evidence = {
  version: 1,
  repo: 'facebook/astryx',
  pr,
  headSha,
  testedSha: verdict.context?.sha ?? null,
  baseSha: verdict.context?.baseSha ?? null,
  run: {id: Number(runId), attempt: Number(runAttempt)},
  verdict,
};
fs.writeFileSync(path.join(output, 'evidence.json'), `${JSON.stringify(evidence, null, 2)}\n`);
fs.writeFileSync(path.join(output, 'verdict.json'), `${JSON.stringify(verdict, null, 2)}\n`);
fs.writeFileSync(
  path.join(output, 'index.html'),
  renderReport(verdict, {acceptHint: '/accept-visual <why every changed frame is correct>'}),
);

process.stdout.write(
  `Validated ${verdict.changes.length} visual delta(s) for PR #${pr}, head ${headSha.slice(0, 12)}, run ${runId}/${runAttempt}.\n`,
);
